import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Сайты вакансий и формы приёма просят файлы определённого размера — и 200 КБ встречается там очень часто. Это достаточно много для чёткого фото и достаточно мало для любой системы.</p>\n<p>Но лимит веса — только часть правил. Порталы проверяют формат, размеры в пикселях, размер лица на фото и читаемость документов.</p>\n<p>Эта статья расскажет, как подготовить все файлы для портала: фото профиля, документы резюме и подпись — и пройти проверку с первой попытки.</p>\n<h2 id=\"why-portals-use-200kb\">Почему порталы используют 200 КБ</h2>\n<p>Порталы хранят миллионы профилей. Файлы на 200 КБ держат базы данных быстрыми, а страницы профилей — лёгкими.</p>\n<p>При 200 КБ фото профиля выглядит профессионально. Рекрутер видит чёткое лицо, а не пиксельный квадрат.</p>\n<p>Лимит 200 КБ — это компромисс между качеством и стоимостью хранения. Портал получает хорошие изображения, не платя за хранение огромных файлов.</p>\n<p>Некоторые порталы унаследовали лимит от старых систем. Но даже сегодня 200 КБ — разумный стандарт для документов и фото.</p>\n<h2 id=\"profile-photo-rules\">Правила для фото профиля</h2>\n<p>Фото профиля должно быть свежим, чётким и деловым. Снимите его при дневном свете на однотонном фоне.</p>\n<p>Лицо должно занимать большую часть кадра. Многие порталы требуют, чтобы лицо заполняло заданную долю изображения.</p>\n<p>Смотрите прямо в камеру, без очков с затемнёнными стёклами и головных уборов, если правила их не разрешают. Нейтральное выражение лица — самый безопасный выбор.</p>\n<p>Обрежьте кадр до головы и плеч до сжатия. Лицо крупным планом получает большую долю бюджета в 200 КБ.</p>\n<p>Проверьте фото в том размере, в котором его увидят рекрутеры. Маленький круглый кадр скрывает мелкие дефекты, но не спасает размытое лицо.</p>\n<h2 id=\"resume-documents\">Документы резюме</h2>\n<p>Резюме обычно загружают как PDF, а не как изображение. Но фото и сканы сертификатов для резюме — это изображения, и они подчиняются лимиту 200 КБ.</p>\n<p>Сканируйте документы в оттенках серого, когда цвет не нужен. Серый скан несёт меньше данных и легко достигает 200 КБ.</p>\n<p>Проверьте мелкий текст после сжатия. Основной текст обычно выживает, а вот подписи и печати могут смягчиться.</p>\n<p>Если портал просит несколько документов, готовьте каждый отдельно. У сертификата и фото разные потребности, и один формат не подходит всем.</p>\n<p>Называйте файлы по содержанию: certificate-200kb.jpg найти проще, чем scan-01.jpg.</p>\n<h2 id=\"signature-rules\">Правила для подписи</h2>\n<p>Подпись — это в основном белое пространство, поэтому она сжимается легко. Чистый скан подписи достигает 200 КБ с большим запасом.</p>\n<p>Сканируйте подпись с разумным разрешением: 300 DPI вполне достаточно. Скан на 1200 DPI создаёт огромный файл, который придётся сильнее уменьшать.</p>\n<p>Выровняйте скан перед загрузкой. Наклонённая подпись тратит пиксели на пустые углы.</p>\n<p>Если после сжатия подпись выглядит серой, слегка поднимите контраст. Тёмные чернила переносят сжатие лучше бледных линий.</p>\n<p>Сохраняйте подпись отдельным файлом. Формы часто просят фото и подпись раздельно, и путаница здесь дорого обходится.</p>\n<h2 id=\"format-choice-portals\">Выбор формата для порталов</h2>\n<p>JPG — самый безопасный формат для порталов. Его принимают почти все системы, и для фото он даёт чистые результаты при 200 КБ.</p>\n<p>WebP лучше по качеству при том же весе, но его принимают не все порталы. Проверьте список принимаемых форматов, прежде чем выбирать WebP.</p>\n<p>PNG подходит для сканов с резким текстом и плоской графикой. Для фото PNG тратит бюджет впустую и часто не умещается в лимит.</p>\n<p>Когда правила портала не уточняют формат, берите JPG. Это выбор, который почти никогда не подводит.</p>\n<p>Держите под рукой обе версии — JPG и WebP. Если портал отклонит одну, вторая будет готова за секунды.</p>\n<h2 id=\"step-by-step-portal\">Пошаговая подготовка для портала</h2>\n<p>Сначала прочитайте все правила портала. Запишите лимит веса, требуемые размеры, принимаемые форматы и правила для лица.</p>\n<p>Затем подготовьте исходники: свежее фото, чистые сканы документов и аккуратную подпись. Хороший исходник — половина успеха.</p>\n<p>Сожмите каждый файл отдельно с помощью <a href=\"/ru/szhat-izobrazhenie-do-200-kb/\">компрессора до 200 КБ</a>. Проверьте каждый результат в полном размере.</p>\n<p>Назовите файлы понятно: имя, назначение и размер. Например, ivan-photo-200kb.jpg.</p>\n<p>Загрузите файлы на портал и используйте его предпросмотр. Это последний шанс поймать проблему до отправки.</p>\n<h2 id=\"common-rejections\">Частые причины отказа</h2>\n<p>Неправильный формат — самая частая причина. Файл WebP на портале, который принимает только JPG, отклоняется мгновенно.</p>\n<p>Неправильные размеры — вторая причина. Портал проверяет пиксели отдельно от веса, и файл на 199 КБ с неверными размерами не пройдёт.</p>\n<p>Слишком маленькое лицо — третья причина. Если лицо занимает малую часть кадра, портал может отклонить фото, даже если вес правильный.</p>\n<p>Нечитаемый текст — четвёртая причина. Скан сертификата с размытыми буквами бесполезен, каким бы лёгким он ни был.</p>\n<p>Читайте точное сообщение об ошибке. Оно говорит, что именно не так, и у каждой проблемы своё решение.</p>\n<h2 id=\"multiple-documents\">Несколько документов сразу</h2>\n<p>Многие порталы просят сразу несколько файлов: фото, резюме, сертификаты и подпись. Готовьте их заранее, а не в день дедлайна.</p>\n<p>Сжимайте файлы по одному, даже если инструмент поддерживает партии. У каждого документа свои потребности, и общая настройка подходит не всем.</p>\n<p>Проверяйте каждый файл отдельно после сжатия. Сертификат с размытым текстом и портрет с мягким лицом — разные проблемы.</p>\n<p>Храните все файлы в одной папке с названием заявки. Папка «вакансия-2026» с файлами внутри избавит от путаницы.</p>\n<p>Загружайте файлы по одному и проверяйте предпросмотр каждого. Массовая загрузка скрывает ошибки, которые видны при поштучной проверке.</p>\n<h2 id=\"mobile-applications\">Подача заявки с телефона</h2>\n<p>Большинство соискателей подают заявки с телефона. Порядок тот же, но источник файлов важен вдвойне.</p>\n<p>Берите оригинал из галереи, а не копию из мессенджера. Мессенджеры уменьшают фото ещё до того, как вы их увидите.</p>\n<p>Фото HEIC с iPhone загружайте напрямую в инструмент. Он читает их и конвертирует при сжатии.</p>\n<p>После скачивания проверьте файл в приложении «Файлы». Убедитесь, что размер меньше 200 КБ, прежде чем возвращаться на портал.</p>\n<p>Держите портал открытым в другой вкладке. Переключение между вкладками быстрее, чем поиск ссылки заново.</p>\n<h2 id=\"after-submission\">После отправки</h2>\n<p>Сохраните копии всех отправленных файлов. Если портал потеряет заявку, вы сможете отправить её снова за минуты.</p>\n<p>Запишите, куда и когда вы отправили каждый файл. Простая таблица с датами экономит часы при отслеживании откликов.</p>\n<p>Не удаляйте оригиналы после отправки. Другой портал может потребовать тот же файл в другом размере.</p>\n<p>Если придёт отказ, прочитайте его внимательно. Часто проблема в файле, а не в вашей квалификации, и её можно исправить.</p>\n<p>Если заявку приняли, сохраните подтверждение. Скриншот страницы подтверждения — хорошая страховка.</p>\n<h2 id=\"beyond-200kb\">Когда нужно больше 200 КБ</h2>\n<p>Некоторые порталы разрешают 500 КБ или больше. Если ваш файл страдает при 200 КБ, а портал разрешает больше, используйте больший размер.</p>\n<p>Детальная инфографика или широкий сертификат с мелким текстом могут нуждаться в 500 КБ. Проверьте результат при 200 КБ и поднимитесь, если текст размыт.</p>\n<p>Для портфолио с фото работ 200 КБ иногда мало. Используйте <a href=\"/ru/szhat-izobrazhenie-do-500-kb/\">компрессор до 500 КБ</a>, если платформа это позволяет.</p>\n<p>Правило простое: используйте самый большой размер, который разрешает портал. Меньше — не лучше, если только форма этого не требует.</p>\n<p>А если портал требует меньше, например 100 КБ, используйте <a href=\"/ru/szhat-izobrazhenie-do-100-kb/\">компрессор до 100 КБ</a> и проверьте результат так же внимательно.</p>\n<h2 id=\"photo-day\">День фото: как подготовиться</h2>\n<p>Выделите отдельный день для фото на документы. Спешка в день дедлайна — худший фотограф.</p>\n<p>Наденьте однотонную одежду без мелкого узора. Мелкая клетка дорого обходится при сжатии, а однотонный цвет стоит почти ничего.</p>\n<p>Встаньте у светлой пустой стены при дневном свете. Ровный свет даёт чистую кожу и резкие глаза.</p>\n<p>Сделайте несколько кадров и выберите лучший. Один удачный кадр стоит десяти посредственных.</p>\n<p>Сожмите выбранный кадр сразу, пока свет и настроение свежи в памяти. Откладывание на потом только добавляет стресса.</p>\n<h2 id=\"document-checklist\">Чек-лист документов</h2>\n<p>Фото профиля: свежее, чёткое, лицо по центру, меньше 200 КБ, формат JPG.</p>\n<p>Скан паспорта или удостоверения: читаемый текст, ровные края, меньше 200 КБ.</p>\n<p>Скан сертификата: мелкий текст читаем, печати видны, меньше 200 КБ.</p>\n<p>Подпись: тёмные чернила, белый фон, ровный скан, меньше 200 КБ.</p>\n<p>Пройдитесь по списку перед загрузкой. Один пропущенный пункт может стоить целой заявки.</p>\n<h2 id=\"deadline-pressure\">Дедлайны и спешка</h2>\n<p>Готовьте файлы за несколько дней до дедлайна. В последний день порталы перегружены, а нервы — на пределе.</p>\n<p>Держите все файлы в одной папке с понятными именами. Поиск файла в день дедлайна — потерянное время.</p>\n<p>Проверьте каждый файл заранее, а не в момент загрузки. Предпросмотр портала — последняя проверка, а не первая.</p>\n<p>Если портал упал в день дедлайна, не паникуйте. Сохраните файлы и попробуйте снова через час — системы восстанавливаются.</p>\n<p>Отправляйте заявку утром, а не ночью. Утром и вы свежее, и поддержка портала на месте.</p>\n<h2 id=\"reusing-photos\">Повторное использование фото</h2>\n<p>Одно хорошее фото можно использовать на нескольких порталах. Но проверяйте правила каждого: размеры и форматы отличаются.</p>\n<p>Не используйте файл, сделанный для одного портала, на другом без проверки. Файл на 50 КБ для экзамена не подойдёт для сайта вакансий с лимитом 200 КБ — вернее, подойдёт, но будет выглядеть хуже, чем мог бы.</p>\n<p>Лучше сожмите заново с оригинала под каждый портал. Это занимает минуту, а результат соответствует правилам именно этого портала.</p>\n<p>Храните оригинал вечно. Сжатая копия не превращается обратно в качественный оригинал.</p>\n<p>Ведите запись: какое фото куда отправлено. Это помогает, когда рекрутер спрашивает о конкретном профиле.</p>\n<h2 id=\"verification-steps\">Шаги проверки</h2>\n<p>Проверьте вес файла: он должен быть меньше 200 КБ, обычно от 198 до 199,9 КБ.</p>\n<p>Проверьте формат: он должен быть в списке принимаемых форматов портала.</p>\n<p>Проверьте размеры в пикселях: откройте свойства изображения и прочитайте число напрямую.</p>\n<p>Проверьте изображение в полном размере: лицо чёткое, текст читаем, края не обрезаны.</p>\n<p>Проверьте предпросмотр портала после загрузки. Это взгляд портала на ваш файл, и он решает всё.</p>\n<h2 id=\"long-term-habits\">Привычки на долгую перспективу</h2>\n<p>Держите папку «документы» в порядке: оригиналы отдельно, сжатые копии — по заявкам. Порядок сейчас экономит часы потом.</p>\n<p>Обновляйте фото профиля раз в год. Старое фото вводит рекрутеров в заблуждение и выглядит непрофессионально.</p>\n<p>Сохраняйте новые сертификаты сразу после получения. Скан, сделанный вовремя, чище скана, сделанного в спешке.</p>\n<p>Пересматривайте стандарты порталов раз в год. Лимиты меняются, и файл, сделанный год назад, может не подойти сегодня.</p>\n<p>И помните: хорошая подготовка — это не бюрократия, а уважение к своему времени и к людям, которые будут смотреть ваши документы.</p>\n<p>Когда подаётесь на несколько вакансий сразу, сделайте таблицу: компания, портал, лимит, формат и дата подачи. Одна таблица избавляет от путаницы, когда откликов много.</p>\n<p>Проверяйте фото на том устройстве, где его увидят рекрутеры. Фото, хорошее на компьютере, на телефоне может выглядеть иначе — и наоборот.</p>\n<p>Не используйте старые фото: рекрутер должен узнать вас на собеседовании. Фото старше двух лет вводит людей в заблуждение.</p>\n<p>Если портал просит фото в определённой одежде или на определённом фоне, следуйте правилам буквально. Творчество здесь не оценят, а заявку отклонят.</p>\n<p>Держите копии всех отправленных файлов в одной папке с названием вакансии. Если рекрутер попросит файл повторно, вы отправите его за секунды.</p>\n<p>Когда получаете отказ, не удаляйте файлы: другая вакансия может потребовать те же документы. Храните их до конца поиска работы.</p>\n<p>Проверяйте почту после подачи заявки: порталы часто присылают подтверждение или просьбу исправить файл. Быстрый ответ показывает вашу внимательность.</p>\n<p>Если портал позволяет, добавьте сопроводительное письмо отдельным файлом. Оно не заменяет резюме, но помогает выделиться среди других кандидатов.</p>\n<p>Не подавайте одну и ту же заявку дважды: дубликаты раздражают рекрутеров и могут привести к отклонению обеих заявок.</p>\n<p>Следите за сроками: подавайте заявку за несколько дней до дедлайна, а не в последний час. В день дедлайна порталы перегружены.</p>\n<p>И помните: аккуратные документы — это первое впечатление. Работодатель видит ваши файлы раньше, чем вас, и они должны говорить о вас хорошо.</p>\n<p>Когда готовитесь к собеседованию, перечитайте требования вакансии и сверьте документы с ними. Один недостающий файл может стоить приглашения.</p>\n<p>Держите резюме актуальным: обновляйте его после каждого проекта или курса. Резюме, не обновлявшееся год, выглядит заброшенным.</p>\n<p>Просите друзей проверить ваши документы свежим взглядом. Чужие глаза замечают ошибки, которые вы перестали видеть.</p>\n<p>Если портал позволяет загрузить дополнительные файлы, добавьте рекомендации или сертификаты. Лишние доказательства редко вредят.</p>\n<p>Сохраняйте спокойствие при отказе: часто проблема в файле, а не в вас. Исправьте файл и подайтесь снова.</p>\n<p>Ведите дневник поиска работы: куда подались, когда и какой ответ получили. Записи помогают не подавать одну заявку дважды.</p>\n<p>И помните: документы — это только дверь. Ваша задача — пройти через неё, а дальше решают ваши навыки и опыт.</p>\n<p>Чек-лист перед загрузкой: вес меньше 200 КБ, формат из списка принимаемых, размеры в пикселях совпадают, лицо по центру, текст на сканах читается.</p>\n<p>Рекрутер видит фото раньше, чем резюме: аккуратный снимок создаёт первое впечатление за секунды. Потратьте на него столько же внимания, сколько на текст резюме.</p>\n<p>Если у портала есть мобильное приложение, проверьте загрузку и в нём: иногда приложение принимает форматы иначе, чем сайт.</p>\n<p>Сохраняйте подтверждение подачи заявки: скриншот страницы с номером заявки пригодится, если портал потеряет ваши файлы.</p>\n<p>Если портал просит фото в определённом соотношении сторон, обрежьте кадр заранее под это соотношение. Так вы сохраните контроль над композицией.</p>\n<p>Держите под рукой обе версии файла — JPG и WebP. Загрузите ту, которую примет система, а вторую сохраните как запасную.</p>\n<p>Полное руководство по этому размеру читайте в статье <a href=\"/ru/blog/kak-szhat-izobrazhenie-do-200-kb-polnoe-rukovodstvo/\">Как сжать изображение до 200 КБ: полное руководство</a>. Практические шаги — в статье <a href=\"/ru/blog/kak-szhat-izobrazhenie-do-200-kb/\">Как сжать изображение до 200 КБ</a>. Для нестандартных лимитов используйте <a href=\"/ru/szhat-izobrazhenie-do-tselego-razmera/\">компрессор до точного размера файла</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Какого размера должно быть фото профиля для сайта вакансий?","answer":"Чаще всего — меньше 200 КБ, в формате JPG, с лицом по центру кадра. Точные размеры в пикселях зависят от портала: прочитайте его правила перед сжатием. Фото на 200 КБ выглядит профессионально и проходит почти все лимиты."},{"question":"Можно ли загрузить на сайт вакансий фото в формате WebP?","answer":"Только если портал явно принимает WebP. Многие старые системы принимают только JPG и PNG. Если правила не уточняют формат, используйте JPG — это самый безопасный выбор."},{"question":"Мой скан сертификата размылся после сжатия до 200 КБ. Что пошло не так?","answer":"Скорее всего, исходный скан был низкого качества или размеры уменьшили слишком сильно. Для текста размеры важнее качества: держите размеры щедрыми и используйте WebP. Если текст всё равно размыт, поднимитесь до 500 КБ, если портал это позволяет."},{"question":"Нужно ли профессиональное фото для сайта вакансий?","answer":"Не обязательно студийное, но фото должно быть чётким, свежим и деловым. Хороший свет у окна и однотонный фон дают результат не хуже студии. Главное — резкое лицо и аккуратный вид."},{"question":"Можно ли использовать одно и то же сжатое фото на нескольких порталах?","answer":"Да, если правила порталов совпадают. Но лучше сжимать заново с оригинала под каждый портал: размеры и форматы отличаются, а свежая копия всегда соответствует правилам именно этого портала."},{"question":"Почему портал всё равно отклоняет моё фото на 199 КБ?","answer":"Прочитайте точное сообщение об ошибке: проблема часто не в весе, а в формате или размерах в пикселях. Проверьте список принимаемых форматов и требуемые габариты. Вес 199 КБ при правильных формате и размерах проходит почти всегда."}];
